blocks.code:
.card {
  box-sizing: border-box;
  width: 300px;
  padding: 20px;
  border: 2px solid #26344D;
}

.course-card {
  box-sizing: border-box;
  width: 100%;
  padding: 24px;
  margin-bottom: 20px;
  border: 1px solid #26344D;
  border-radius: 16px;
  background-color: #121A2B;
}

.course-level {
  display: inline-block;
  margin-bottom: 12px;
}

.course-card h2 {
  margin: 0 0 10px;
}

.course-card p {
  margin: 0 0 20px;
}

.field {
  margin-bottom: 18px;
}

.field input {
  box-sizing: border-box;
  width: 100%;
  padding: 12px 14px;
  border: 1px solid #26344D;
  border-radius: 10px;
}

.profile {
  box-sizing: border-box;
  width: 100%;
  padding: 24px;
  margin-bottom: 20px;
  border: 1px solid #26344D;
  border-radius: 16px;
  background-color: #121A2B;
}

.profile h2 {
  margin: 0 0 10px;
}

.profile p {
  margin: 0 0 18px;
}
